#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==1L);all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");library(shiny);`%||%`<-function(l,r)if(is.null(l)||!length(l))r else l;source(file.path(root,"app/shiny/R/ui_qc.R"),local=TRUE)
args_for<-function(mode,force=FALSE,signature="sig")c("--samples","a,b",if(mode=="preview")"--dry-run",if(mode=="run"&&force)"--force",if(mode=="run")c("--cache-signature",signature))
preview<-args_for("preview");run<-args_for("run");forced<-args_for("run",TRUE);stopifnot("--dry-run"%in%preview,!"--force"%in%preview,diagnostic_action_label("preview")=="Preview diagnostics",!"--dry-run"%in%run,diagnostic_action_label("run")=="Run diagnostics","--cache-signature"%in%run,diagnostic_action_label("run",TRUE)=="Use cached diagnostics","--force"%in%forced,diagnostic_action_label("run",TRUE,TRUE)=="Rerun diagnostics");cat("PASS\n")
